CREATE OR REPLACE FUNCTION public.web_reissue_request(p_token text, p_invoice_number text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'extensions', 'public', 'pg_temp'
AS $function$
declare v_emp employees := staff_session_employee(p_token); v_inv uuid;
begin
